            raise ConfigError(f'Error loading TOML file: {e}')

    errors = []

    for key, value in env_map.items():
        if key not in config:
            errors.append(f'Unknown environment key: {key}')
        else:
            try:
                config[key] = coerce_value(value, type(config[key]))
            except ValueError as e:
                errors.append(f'Error coercing key {key}: {e}')

    if errors:
        raise ConfigError('\n'.join(errors))

    return config


def merge_toml(base, toml):
    for key, value in toml.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            merge_toml(base[key], value)
        else:
            base[key] = value



def coerce_value(value, target_type):
    if target_type is bool:
        if str(value).lower() in ('true', '1', 'yes'):
            return True
        if str(value).lower() in ('false', '0', 'no'):
            return False
        raise ValueError(f'Cannot coerce {value} to bool')

    try:
        return target_type(value)
    except ValueError:
        raise ValueError(f'Cannot coerce {value} to {target_type}')

import pytest
from envcfg import load_config, ConfigError


@pytest.fixture
def default_config():
    return {
        'server': {
            'host': 'localhost',
            'port': 8080,
            'debug': True
        },
        'db': {
            'url': 'sqlite://db'
        }
    }

def test_load_config_only_defaults(default_config):
    config = load_config(default_config)
    assert config == default_config

def test_load_config_with_toml(default_config, tmp_path):
    toml_file = tmp_path / 'config.toml'
    toml_file.write_text('[server]
host = "127.0.0.1"')
    config = load_config(default_config, toml_path=str(toml_file))
    assert config['server']['host'] == '127.0.0.1'
    assert config['server']['port'] == 8080

def test_load_config_with_env_vars(default_config):
    env = {
        'APP_SERVER__PORT': '9090',
        'APP_DB__URL': 'postgres://db'
    }
    config = load_config(default_config, env_map=env)
    assert config['server']['port'] == 9090
    assert config['db']['url'] == 'postgres://db'

def test_load_config_nested_override(default_config):
    env = {'APP_SERVER__HOST': '1.1.1.1'}
    config = load_config(default_config, env_map=env)
    assert config['server']['host'] == '1.1.1.1'
    assert config['server']['port'] == 8080

def test_load_config_missing_toml(default_config):
    config = load_config(default_config, toml_path='non_existent.toml')
    assert config == default_config

def test_load_config_coerce_bool(default_config):
    env = {'APP_SERVER__DEBUG': 'false'}
    config = load_config(default_config, env_map=env)
    assert config['server']['debug'] is False

def test_load_config_coerce_bool_yes(default_config):
    env = {'APP_SERVER__DEBUG': 'yes'}
    config = load_config(default_config, env_map=env)
    assert config['server']['debug'] is True

